/* Повні конспекти 7 класу для сторінки уроку. Згенеровано tools/make_notes.py з Google Docs — руками не правити. */
window.NOTES = Object.assign(window.NOTES || {}, {
"7-03": "<h3><b>1. Що можна налаштувати у скриньці</b></h3><div class=\"ntable\"><table><thead><tr><th>Налаштування</th><th>Для чого</th></tr></thead><tbody><tr><td data-th=\"Налаштування\">Підпис</td><td data-th=\"Для чого\">автоматично додається в кінець листа: ім'я, клас, школа</td></tr><tr><td data-th=\"Налаштування\">Папки та позначки</td><td data-th=\"Для чого\">розкладають листи по темах: школа, гуртки, розсилки</td></tr><tr><td data-th=\"Налаштування\">Фільтри</td><td data-th=\"Для чого\">самі переміщують, позначають або вилучають листи за умовою</td></tr><tr><td data-th=\"Налаштування\">Пересилання</td><td data-th=\"Для чого\">копія кожного листа йде на іншу скриньку</td></tr><tr><td data-th=\"Налаштування\">Автовідповідач</td><td data-th=\"Для чого\">надсилає готову відповідь, поки ви у від'їзді</td></tr><tr><td data-th=\"Налаштування\">Сповіщення</td><td data-th=\"Для чого\">повідомляють про новий лист на телефоні</td></tr><tr><td data-th=\"Налаштування\">Двоетапна перевірка</td><td data-th=\"Для чого\">вхід підтверджують кодом — головний захист скриньки</td></tr><tr><td data-th=\"Налаштування\">Резервна адреса й телефон</td><td data-th=\"Для чого\">дають змогу відновити доступ, якщо забули пароль</td></tr></tbody></table></div><div class=\"def\"><b>Фільтр</b> — правило, за яким поштова служба автоматично виконує дію з усіма листами, що відповідають заданій умові: від кого, з якими словами в темі, з вкладенням.</div><h3><b>2. З чого складається лист</b></h3><div class=\"ntable wide\"><table><thead><tr><th>Поле</th><th>Що в ньому</th><th>Коли використовують</th></tr></thead><tbody><tr><td data-th=\"Поле\">Кому</td><td data-th=\"Що в ньому\">адреса основного одержувача</td><td data-th=\"Коли використовують\">той, від кого чекаєте відповіді</td></tr><tr><td data-th=\"Поле\">Копія (Cc)</td><td data-th=\"Що в ньому\">адреси тих, хто має бути в курсі</td><td data-th=\"Коли використовують\">класний керівник, батьки</td></tr><tr><td data-th=\"Поле\">Прихована копія (Bcc)</td><td data-th=\"Що в ньому\">адреси, невидимі для інших</td><td data-th=\"Коли використовують\">розсилка багатьом людям одразу</td></tr><tr><td data-th=\"Поле\">Тема</td><td data-th=\"Що в ньому\">кілька слів про зміст</td><td data-th=\"Коли використовують\">завжди; лист без теми часто не читають</td></tr><tr><td data-th=\"Поле\">Текст</td><td data-th=\"Що в ньому\">звертання, суть, підпис</td><td data-th=\"Коли використовують\">завжди</td></tr><tr><td data-th=\"Поле\">Вкладення</td><td data-th=\"Що в ньому\">прикріплені файли</td><td data-th=\"Коли використовують\">документи, фото, презентації</td></tr></tbody></table></div><p class=\"nnote\"><i>Прихована копія потрібна не для таємниць, а для ввічливості: коли лист іде тридцятьом людям, не варто показувати кожному адреси решти.</i></p><h3><b>3. Правила електронного листування</b></h3><ul><li>тема має відповідати змісту: не «Привіт», а «Реферат з інформатики, Ткачук, 7-Б»;</li><li>починають зі звертання, закінчують підписом;</li><li>одна думка — один абзац, абзаци короткі;</li><li>перевіряють орфографію: лист із помилками справляє те саме враження, що й брудний зошит;</li><li>«Відповісти» — лише авторові, «Відповісти всім» — усім одержувачам; їх легко переплутати;</li><li>великі файли не надсилають вкладенням: більшість служб обмежує його обсягом близько 25 МБ, тому завантажують файл у хмарне сховище й надсилають посилання;</li><li>файлу дають зрозуміле ім'я: Реферат_Ткачук_7Б.docx, а не Документ1.docx;</li><li>відповідають протягом доби, навіть якщо це коротке «отримав, дякую».</li></ul><h3><b>4. Етикет у темі й тоні листа</b></h3><div class=\"ntable\"><table><thead><tr><th>Не варто</th><th>Краще</th></tr></thead><tbody><tr><td data-th=\"Не варто\">ПИСАТИ ВЕЛИКИМИ ЛІТЕРАМИ</td><td data-th=\"Краще\">звичайний текст: великі літери читаються як крик</td></tr><tr><td data-th=\"Не варто\">«Привіт, зроби», без пояснень</td><td data-th=\"Краще\">звертання, суть прохання, термін</td></tr><tr><td data-th=\"Не варто\">Порожня тема</td><td data-th=\"Краще\">коротка тема, що описує зміст</td></tr><tr><td data-th=\"Не варто\">Десять листів поспіль</td><td data-th=\"Краще\">один лист із усіма запитаннями</td></tr><tr><td data-th=\"Не варто\">Емодзі в діловому листі</td><td data-th=\"Краще\">нейтральний тон</td></tr></tbody></table></div><h3><b>Завдання</b></h3><p class=\"ntask\"><b>Завдання 1.</b> Дай відповідь на запитання.</p><p>1) Навіщо потрібен фільтр, якщо листи й так можна переносити вручну?</p><p>2) Чим поле «Копія» відрізняється від «Прихованої копії»?</p><p>3) Що дає двоетапна перевірка?</p><p class=\"ntask\"><b>Завдання 2.</b> Сформулюй тему листа для кожної ситуації.</p><p>1) Надсилаєш учителеві реферат з біології.</p><p>2) Просиш однокласника надіслати конспект за 17 вересня.</p><p>3) Повідомляєш тренера, що пропустиш тренування у вівторок.</p><p>4) Запитуєш у бібліотеці, чи є потрібна книжка.</p><p class=\"ntask\"><b>Завдання 3.</b> Знайди помилки в листі та перепиши його правильно.</p><p>Тема: (порожня)</p><p>«ДОБРОГО ДНЯ ЗРОБІТЬ БУДЬ ЛАСКА ШВИДШЕ Я ВЧОРА НАДСИЛАВ АЛЕ ВИ НЕ ВІДПОВІЛИ ФАЙЛ У ВКЛАДЕННІ Документ1.docx»</p><p>Вкладення: відео 380 МБ.</p><p class=\"ntask\"><b>Завдання 4.</b> Яке налаштування скриньки допоможе?</p><p>1) Усі листи з розсилки магазину мають одразу потрапляти в окрему папку.</p><p>2) Ім'я, клас і школа мають з'являтися в кінці кожного листа самі.</p><p>3) Ти забув пароль і не можеш увійти.</p><p>4) Хтось дізнався твій пароль і намагається увійти в скриньку.</p><p class=\"ntask\"><b>Завдання 5.</b> Кому, копія чи прихована копія?</p><p>1) Лист учителеві з домашнім завданням, класному керівникові — для відома.</p><p>2) Запрошення на шкільне свято для 28 батьків.</p><p>3) Запит до адміністрації школи від імені класу.</p><p>4) Відповідь на лист, у якому було п'ятеро одержувачів, але відповідь цікавить лише автора.</p><p class=\"ntask\"><b>Завдання 6.</b> Познач, чи згоден ти з твердженням: так або ні.</p><p>1) Лист без теми — нормальна практика ділового листування.</p><p>2) Фільтр може автоматично перемістити лист у потрібну папку.</p><p>3) Адреси в полі «Прихована копія» бачать усі одержувачі.</p><p>4) Файл обсягом 300 МБ зручно надіслати вкладенням.</p><p>5) Двоетапна перевірка захищає скриньку навіть тоді, коли пароль став відомий іншим.</p><p>6) «Відповісти всім» надсилає відповідь лише авторові листа.</p><p class=\"ntask\"><b>Завдання 7*.</b> Налаштуй свою скриньку й опиши це письмово. Створи підпис, одну папку та один фільтр до неї. Запиши, яку умову ти задав фільтру й що він робить із листами.</p>",
"7-04": "<h3><b>1. Небажана пошта</b></h3><div class=\"def\"><b>Спам</b> — масові листи, яких одержувач не замовляв: реклама, розсилки, сумнівні пропозиції.</div><div class=\"def\"><b>Фішинг</b> — шахрайський лист, який удає лист від банку, школи, служби доставки чи державного сервісу, щоб виманити пароль, код або платіжні дані.</div><h3><b>2. Як розпізнати шахрайський лист</b></h3><div class=\"ntable\"><table><thead><tr><th>Ознака</th><th>Що з нею робити</th></tr></thead><tbody><tr><td data-th=\"Ознака\">Тиск часом: «лише сьогодні», «заблокуємо за годину»</td><td data-th=\"Що з нею робити\">не поспішати — саме на поспіх розрахунок</td></tr><tr><td data-th=\"Ознака\">Адреса відправника схожа, але не та</td><td data-th=\"Що з нею робити\">звірити домен символ за символом</td></tr><tr><td data-th=\"Ознака\">Звертання «Шановний користувач»</td><td data-th=\"Що з нею робити\">справжня служба звертається на ім'я</td></tr><tr><td data-th=\"Ознака\">Помилки й дивні формулювання</td><td data-th=\"Що з нею робити\">часто це машинний переклад</td></tr><tr><td data-th=\"Ознака\">Просять пароль, код з СМС або номер картки</td><td data-th=\"Що з нею робити\">жодна служба цього не запитує</td></tr><tr><td data-th=\"Ознака\">Посилання, текст якого не збігається з адресою</td><td data-th=\"Що з нею робити\">навести вказівник і прочитати справжню адресу</td></tr><tr><td data-th=\"Ознака\">Несподіване вкладення .exe, .zip, .scr</td><td data-th=\"Що з нею робити\">не відкривати, вилучити лист</td></tr><tr><td data-th=\"Ознака\">Обіцянка виграшу чи грошей нізащо</td><td data-th=\"Що з нею робити\">вилучити й повідомити дорослих</td></tr></tbody></table></div><p><b>Якщо лист виглядає як від відомої служби, не переходять за посиланням із листа, а відкривають офіційний застосунок або сайт самостійно.</b></p><h3><b>3. Гіперпосилання в листах</b></h3><div class=\"def\"><b>Гіперпосилання</b> — фрагмент тексту або зображення, клацання по якому відкриває інший документ чи вебсторінку.</div><ul><li>посилання додають сполученням Ctrl + K або кнопкою «Вставити посилання»;</li><li>текст посилання має пояснювати, куди воно веде: «розклад на жовтень», а не «тут»;</li><li>перед клацанням наводять вказівник і дивляться адресу внизу вікна;</li><li>скорочені посилання приховують справжню адресу — з незнайомих джерел їх не відкривають.</li></ul><h3><b>4. Онлайн-перекладачі</b></h3><div class=\"ntable\"><table><thead><tr><th>Сильні сторони</th><th>Обмеження</th></tr></thead><tbody><tr><td data-th=\"Сильні сторони\">швидко дають загальний зміст тексту</td><td data-th=\"Обмеження\">не розуміють контексту й жартів</td></tr><tr><td data-th=\"Сильні сторони\">перекладають сторінку цілком</td><td data-th=\"Обмеження\">плутають багатозначні слова</td></tr><tr><td data-th=\"Сильні сторони\">озвучують вимову</td><td data-th=\"Обмеження\">помиляються у власних назвах і термінах</td></tr><tr><td data-th=\"Сильні сторони\">працюють з фото й голосом</td><td data-th=\"Обмеження\">текст звучить неприродно для носія мови</td></tr></tbody></table></div><ul><li>перекладений текст перечитують і виправляють, а не вставляють як є;</li><li>перевірити якість можна зворотним перекладом;</li><li>у перекладач не вставляють персональні дані, паролі та чужі листи.</li></ul><p>Матеріали з інтернету можна використовувати у своїй роботі, але з посиланням на джерело: текст, фотографія й відео захищені авторським правом.</p><h3><b>Завдання</b></h3><p class=\"ntask\"><b>Завдання 1.</b> Дай відповідь на запитання.</p><p>1) Чим фішинг небезпечніший за звичайний спам?</p><p>2) Як перевірити, куди насправді веде посилання?</p><p>3) Чому не можна вставляти в онлайн-перекладач персональні дані?</p><p class=\"ntask\"><b>Завдання 2.</b> Перед тобою лист. Випиши всі ознаки шахрайства.</p><p>Від: sluzhba-dostavky@nova-poshta-ua.info</p><p>Тема: ТЕРМІНОВО! Ваша посилка буде знищена сьогодні</p><p>«Шановний користувач! Щоб отримати посилку, протягом 2 годин підтвердіть дані картки за посиланням. Інакше посилку буде повернено відправнику.»</p><p>Вкладення: Posylka_info.exe</p><p class=\"ntask\"><b>Завдання 3.</b> Як вчинити в кожній ситуації?</p><p>1) Прийшов лист «від школи» з проханням увести пароль від шкільної скриньки.</p><p>2) Друг надіслав коротке посилання без жодних пояснень.</p><p>3) На пошту щодня приходить десять рекламних листів від одного магазину.</p><p>4) Ти випадково ввів пароль на підозрілій сторінці.</p><p class=\"ntask\"><b>Завдання 4.</b> Зроби текст посилання зрозумілим.</p><p>1) «Натисни тут».</p><p>2) «Дивись».</p><p>3) «http://school2.vn.ua/rozklad/2026/09/7b.html».</p><p>4) «Файл».</p><p class=\"ntask\"><b>Завдання 5.</b> Оціни переклад. Речення «Він завалив контрольну» перекладач передав англійською як «He filled up the test». Поясни, чому так сталося і як перевірити переклад, не знаючи мови досконало.</p><p class=\"ntask\"><b>Завдання 6.</b> Познач, чи згоден ти з твердженням: так або ні.</p><p>1) Банк може надіслати листа з проханням повідомити код із СМС.</p><p>2) Скорочене посилання приховує справжню адресу сторінки.</p><p>3) Вкладення з розширенням .exe у листі від незнайомця слід відкрити, щоб перевірити.</p><p>4) Матеріали з інтернету можна використовувати з посиланням на джерело.</p><p>5) Онлайн-перекладач завжди враховує контекст речення.</p><p>6) Текст посилання має пояснювати, куди воно веде.</p><p class=\"ntask\"><b>Завдання 7*.</b> Склади для п'ятикласників пам'ятку «П'ять ознак шахрайського листа». Кожен пункт — одне коротке речення й одна порада, що робити.</p>",
"7-05": "<h3><b>1. Хмарні технології</b></h3><div class=\"def\"><b>Хмарні технології</b> — спосіб роботи, за якого документи зберігаються не на комп'ютері користувача, а на віддалених серверах, і доступні з будь-якого пристрою через інтернет.</div><ul><li>файл не треба пересилати: усі працюють з одним документом;</li><li>зміни зберігаються автоматично, «втратити роботу» майже неможливо;</li><li>документ відкривається з комп'ютера, планшета й телефона;</li><li>працювати можна одночасно — видно, хто де редагує;</li><li>мінус один, але важливий: без інтернету доступ обмежений.</li></ul><h3><b>2. Рівні спільного доступу</b></h3><div class=\"ntable wide\"><table><thead><tr><th>Рівень</th><th>Що дозволяє</th><th>Кому надають</th></tr></thead><tbody><tr><td data-th=\"Рівень\">Переглядач</td><td data-th=\"Що дозволяє\">тільки читати</td><td data-th=\"Кому надають\">тим, хто має ознайомитися</td></tr><tr><td data-th=\"Рівень\">Коментатор</td><td data-th=\"Що дозволяє\">читати й залишати коментарі</td><td data-th=\"Кому надають\">рецензентові, учителеві на перевірку</td></tr><tr><td data-th=\"Рівень\">Редактор</td><td data-th=\"Що дозволяє\">змінювати вміст документа</td><td data-th=\"Кому надають\">учасникам спільної роботи</td></tr><tr><td data-th=\"Рівень\">Власник</td><td data-th=\"Що дозволяє\">усе, зокрема вилучення й передавання прав</td><td data-th=\"Кому надають\">автору документа</td></tr></tbody></table></div><p>Доступ надають двома способами: конкретним адресам або посиланням. Варіант «усі, хто має посилання, можуть редагувати» зручний і найнебезпечніший — посилання легко потрапляє далі, ніж планували.</p><h3><b>3. Інструменти спільної роботи</b></h3><div class=\"ntable\"><table><thead><tr><th>Інструмент</th><th>Для чого</th></tr></thead><tbody><tr><td data-th=\"Інструмент\">Коментарі</td><td data-th=\"Для чого\">обговорити фрагмент, не змінюючи тексту</td></tr><tr><td data-th=\"Інструмент\">Згадування через @</td><td data-th=\"Для чого\">адресувати коментар конкретній людині</td></tr><tr><td data-th=\"Інструмент\">Режим пропозицій</td><td data-th=\"Для чого\">запропонувати правку, яку автор прийме або відхилить</td></tr><tr><td data-th=\"Інструмент\">Історія версій</td><td data-th=\"Для чого\">переглянути, хто і що змінив, і повернути попередній варіант</td></tr><tr><td data-th=\"Інструмент\">Спільні папки</td><td data-th=\"Для чого\">тримати всі матеріали проєкту в одному місці</td></tr></tbody></table></div><p class=\"nnote\"><i>Історія версій — головний аргумент у суперечці «хто зіпсував таблицю»: у ній видно і час, і автора кожної зміни.</i></p><h3><b>4. Практична робота 2 «Використання хмарних технологій для колективного опрацювання документів»</b></h3><p class=\"nnote\"><i>Перед роботою — інструктаж з безпеки життєдіяльності.</i></p><p><b>Хід роботи</b></p><ol><li>Створи у хмарному сховищі текстовий документ з іменем Проєкт_Прізвище.</li><li>Додай заголовок і таблицю на три стовпці: «Завдання», «Виконавець», «Термін».</li><li>Надай однокласникові доступ рівня «Редактор» на його адресу.</li><li>Отримай доступ до документа сусіда й заповни в ньому один рядок таблиці.</li><li>Залиши у своєму документі коментар до будь-якого рядка і згадай у ньому однокласника через @.</li><li>Дай відповідь на коментар, який залишили тобі, і познач його як розв'язаний.</li><li>Внеси зміну в чужий документ у режимі пропозицій.</li><li>Відкрий історію версій свого документа й запиши в зошит, хто і коли вносив зміни.</li><li>Зміни рівень доступу однокласника на «Переглядач».</li><li>Скопіюй посилання на документ і надішли його вчителеві листом із темою «ПР2, Прізвище, клас».</li><li>Покажи результат учителеві.</li></ol><h3><b>Завдання</b></h3><p class=\"ntask\"><b>Завдання 1.</b> Дай відповідь на запитання.</p><p>1) Чим спільна робота в хмарі краща за пересилання файлів поштою?</p><p>2) Який рівень доступу надати вчителеві для перевірки роботи?</p><p>3) Навіщо потрібна історія версій?</p><p class=\"ntask\"><b>Завдання 2.</b> Який рівень доступу обрати?</p><p>1) Класний керівник має прочитати оголошення, але не змінювати його.</p><p>2) Троє однокласників разом готують проєкт.</p><p>3) Учитель перевіряє реферат і залишає зауваження.</p><p>4) Документ треба показати всій паралелі лише для ознайомлення.</p><p class=\"ntask\"><b>Завдання 3.</b> Знайди помилки в діях групи.</p><p>«Ми зробили документ і відкрили редагування для всіх, хто має посилання, а посилання виклали в загальний чат школи. Кожен качав собі копію й правив її окремо, а потім ми надсилали копії одне одному поштою. Коли текст зіпсувався, відновити старий варіант не вдалося, бо ніхто не робив резервних копій.»</p><p class=\"ntask\"><b>Завдання 4.</b> Що використати: коментар, пропозицію чи пряме редагування?</p><p>1) Ти помітив помилку в чужому абзаці, але не впевнений, чи це помилка.</p><p>2) Треба виправити явну одруківку у власному тексті.</p><p>3) Ти хочеш переписати чуже речення, лишивши автору право вирішити.</p><p>4) Треба запитати в однокласника, звідки взято цифру в таблиці.</p><p class=\"ntask\"><b>Завдання 5.</b> Розподіли обов'язки в груповому проєкті з чотирьох учнів. Тема — «Комп'ютерні мережі». Запиши, хто що робить, який рівень доступу отримує й у якій формі група перевірятиме роботу одне одного.</p><p class=\"ntask\"><b>Завдання 6.</b> Познач, чи згоден ти з твердженням: так або ні.</p><p>1) У хмарному документі зміни треба зберігати вручну.</p><p>2) Рівень «Коментатор» дозволяє змінювати текст документа.</p><p>3) Історія версій показує автора кожної зміни.</p><p>4) Доступ «усім, хто має посилання, редагування» — найбезпечніший варіант.</p><p>5) Над одним документом можуть одночасно працювати кілька людей.</p><p>6) Режим пропозицій дає змогу автору прийняти або відхилити правку.</p><p class=\"ntask\"><b>Завдання 7*.</b> Склади правила спільної роботи для свого класу. П'ять коротких пунктів: хто дає доступ, як позначають свої правки, що робити з чужим текстом, як домовлятися про терміни, коли закривати доступ.</p>",
"7-06": "<h3><b>1. Штучний інтелект</b></h3><div class=\"def\"><b>Штучний інтелект</b> — здатність комп'ютерної системи виконувати завдання, які раніше потребували людського мислення: розпізнавати мову й зображення, перекладати, прогнозувати, створювати тексти.</div><p>Сучасні системи працюють за принципом машинного навчання: їм показують тисячі прикладів, і вони самі виводять закономірність, замість того щоб діяти за жорстким набором правил.</p><div class=\"ntable\"><table><thead><tr><th>Де працює ШІ</th><th>Що саме робить</th></tr></thead><tbody><tr><td data-th=\"Де працює ШІ\">Голосовий помічник</td><td data-th=\"Що саме робить\">розпізнає мовлення й відповідає</td></tr><tr><td data-th=\"Де працює ШІ\">Онлайн-перекладач</td><td data-th=\"Що саме робить\">перекладає текст і мовлення</td></tr><tr><td data-th=\"Де працює ШІ\">Навігатор</td><td data-th=\"Що саме робить\">прокладає маршрут з урахуванням заторів</td></tr><tr><td data-th=\"Де працює ШІ\">Стрічка новин і рекомендації</td><td data-th=\"Що саме робить\">добирає, що показати саме вам</td></tr><tr><td data-th=\"Де працює ШІ\">Медицина</td><td data-th=\"Що саме робить\">допомагає лікарю помітити зміни на знімку</td></tr><tr><td data-th=\"Де працює ШІ\">Розпізнавання облич</td><td data-th=\"Що саме робить\">розблоковує телефон</td></tr><tr><td data-th=\"Де працює ШІ\">Чат-боти</td><td data-th=\"Що саме робить\">відповідають на типові запитання</td></tr></tbody></table></div><h3><b>2. Про що треба пам'ятати</b></h3><ul><li>система може впевнено видати неправдиву відповідь — її завжди перевіряють у джерелах;</li><li>якщо в навчальних даних була упередженість, вона перейде й у відповіді;</li><li>дипфейк — підроблене відео чи голос реальної людини; побачене й почуте вже не є доказом;</li><li>у сервіси не вводять персональних даних — свої й чужі;</li><li>академічна доброчесність: ШІ може пояснити тему чи перевірити текст, але виконана ним робота не є вашою роботою.</li></ul><h3><b>3. Інтернет речей</b></h3><div class=\"def\"><b>Інтернет речей (IoT)</b> — мережа побутових і промислових пристроїв, які збирають дані за допомогою давачів, обмінюються ними через інтернет і діють без участі людини.</div><div class=\"ntable\"><table><thead><tr><th>Пристрій</th><th>Що вимірює або робить</th></tr></thead><tbody><tr><td data-th=\"Пристрій\">Розумний лічильник</td><td data-th=\"Що вимірює або робить\">передає показання без візиту контролера</td></tr><tr><td data-th=\"Пристрій\">Термостат</td><td data-th=\"Що вимірює або робить\">підтримує температуру, вмикаючи обігрів</td></tr><tr><td data-th=\"Пристрій\">Фітнес-браслет</td><td data-th=\"Що вимірює або робить\">рахує кроки, пульс, сон</td></tr><tr><td data-th=\"Пристрій\">Розумне освітлення</td><td data-th=\"Що вимірює або робить\">вмикається за рухом або за розкладом</td></tr><tr><td data-th=\"Пристрій\">Давач протікання води</td><td data-th=\"Що вимірює або робить\">перекриває воду й надсилає сповіщення</td></tr><tr><td data-th=\"Пристрій\">Метеостанція, давачі якості повітря</td><td data-th=\"Що вимірює або робить\">збирають дані про погоду й забруднення</td></tr><tr><td data-th=\"Пристрій\">Теплиця з автополивом</td><td data-th=\"Що вимірює або робить\">поливає за вологістю ґрунту</td></tr></tbody></table></div><p>Безпека таких пристроїв починається з дрібниці: стандартний пароль «admin» треба змінити, а оновлення — встановлювати. Камера чи колонка з паролем за замовчуванням стає чужими очима й вухами у вашій кімнаті.</p>",
"7-07": "<h3><b>1. Принцип анімації</b></h3><p>Переглядаючи мультфільми, ми бачимо, що зображення рухаються. Насправді на екрані змінюють одне одного нерухомі малюнки — кадри.</p><div class=\"def\"><b>Анімація</b> — рухоме зображення, яке отримують, швидко показуючи один за одним нерухомі малюнки (кадри), що трохи відрізняються між собою.</div><p>Якщо кадри змінюються достатньо часто, око людини не встигає сприйняти кожен малюнок окремо — і ми бачимо рух. На цьому принципі побудовані мультфільми, кіно, анімовані наліпки в месенджерах і GIF-зображення.</p><div class=\"def\"><b>Частота кадрів</b> — кількість кадрів, які показують за одну секунду. Її вимірюють у кадрах на секунду (кадр/с; англ. frames per second, fps).</div><p>Яку частоту кадрів використовують:</p><div class=\"ntable\"><table><thead><tr><th>Де використовують</th><th>Частота кадрів</th></tr></thead><tbody><tr><td data-th=\"Де використовують\">Перші фільми</td><td data-th=\"Частота кадрів\">від 16 до 24 кадр/с</td></tr><tr><td data-th=\"Де використовують\">Кінотеатри (стандарт із 1930-х років)</td><td data-th=\"Частота кадрів\">24 кадр/с</td></tr><tr><td data-th=\"Де використовують\">Телебачення (різні системи)</td><td data-th=\"Частота кадрів\">24, 25 або 30 кадр/с</td></tr><tr><td data-th=\"Де використовують\">Комп'ютерні програми</td><td data-th=\"Частота кадрів\">різна — таку, яку задасть автор</td></tr></tbody></table></div><p>Тривалість анімації легко обчислити: <b>тривалість (с) = кількість кадрів : частота кадрів</b>. Наприклад, 100 кадрів при 25 кадр/с триватимуть 100 : 25 = 4 с. І навпаки: <b>кількість кадрів = тривалість · частота кадрів</b>: для 3 с при 24 кадр/с потрібно 3 · 24 = 72 кадри.</p><p>Якщо збільшити частоту, а кількість кадрів не змінювати, анімація стане коротшою і рух буде швидшим.</p><div class=\"def plus\"><span class=\"plusb\">⭐ для 12 балів</span> <b>Тауматроп</b> — іграшка, популярна в XIX столітті: картонний кружечок на двох нитках, з одного боку якого намальовано, наприклад, пташку, а з другого — клітку. Якщо кружечок швидко крутити, малюнки зливаються в один і пташка «сидить» у клітці.</div><p class=\"nnote\"><i>Тауматроп працює за тим самим принципом, що й анімація: око не встигає сприйняти кожне зображення окремо.</i></p><h3><b>2. Мальована анімація</b></h3><p>Для побудови кадрів використовують малюнки, плоскі перекладні маріонетки тощо. Ми розглядатимемо лише мальовану анімацію.</p><div class=\"def\"><b>Мальована анімація</b> — серія мальованих зображень, на кожному з яких об'єкт подано в іншій фазі руху.</div><p>Наприклад, щоб м'яч «підстрибнув», на першому кадрі його малюють унизу, на наступних — щоразу трохи вище, а потім знову нижче. Кожне таке положення м'яча — окрема фаза руху.</p><div class=\"def plus\"><span class=\"plusb\">⭐ для 12 балів</span> <b>Перекладна анімація</b> — анімація, у якій кадри складають не з малюнків, а з плоских фігурок-маріонеток: їх щоразу трохи пересувають і знімають кожне нове положення.</div><p class=\"nnote\"><i>Перший український анімаційний фільм — «Казка про солом'яного бичка». Його створив режисер, сценарист, художник-аніматор В'ячеслав Левандовський 1927 року в Одесі. Замість малюнків у фільмі використано плоскі маріонетки.</i></p><h3><b>3. Редактор двовимірної анімації та його вікно</b></h3><div class=\"def\"><b>Редактор двовимірної анімації</b> — програма для створення плоских (2D) анімацій: у ній малюють об'єкти, розміщують їх на кадрах і переглядають отриманий рух.</div><p>Програм для створення анімацій чимало: Adobe Animate, Blender, Animation Desk, Animaker, TupiTube та ін. TupiTube — вільний редактор двовимірної анімації з відкритим кодом; працювати в ньому можна на комп'ютері, планшеті й навіть мобільному телефоні.</p><p>У підручнику — редактор TupiTube; на уроці працюємо в браузерному «Аніматорі Ліцею», де ці частини називаються так само. «Аніматор Ліцею» відкривається за адресою musthav6.github.io/informatyka/animator.html: нічого встановлювати не треба, він працює і на комп'ютері, і на телефоні.</p><div class=\"ntable\"><table><thead><tr><th>Частина вікна</th><th>Що в ній («Аніматор Ліцею»)</th></tr></thead><tbody><tr><td data-th=\"Частина вікна\">Верхня панель</td><td data-th=\"Що в ній («Аніматор Ліцею»)\">назва проєкту, кнопки «Новий проєкт», «Зберегти», «Мої проєкти»</td></tr><tr><td data-th=\"Частина вікна\">Панель інструментів (ліворуч)</td><td data-th=\"Що в ній («Аніматор Ліцею»)\">Вибір об'єкта, Прямокутник, Еліпс, Трикутник, Лінія, Текст, Малюнок (готові малюнки-емодзі), Заповнення (відерце), Видалити</td></tr><tr><td data-th=\"Частина вікна\">Робоче поле (у центрі)</td><td data-th=\"Що в ній («Аніматор Ліцею»)\">сцена, на якій малюють і рухають об'єкти</td></tr><tr><td data-th=\"Частина вікна\">Колірна палітра (праворуч)</td><td data-th=\"Що в ній («Аніматор Ліцею»)\">кольори штриха й заповнення, код кольору, повзунки R, G, B і Щільність</td></tr><tr><td data-th=\"Частина вікна\">Панель параметрів (праворуч, під палітрою)</td><td data-th=\"Що в ній («Аніматор Ліцею»)\">X, Y, ширина, висота, кут, зсув вибраного об'єкта; ефекти</td></tr><tr><td data-th=\"Частина вікна\">Шари</td><td data-th=\"Що в ній («Аніматор Ліцею»)\">«Статичне тло», «Динамічне тло», «Анімація», «Передній план»</td></tr><tr><td data-th=\"Частина вікна\">Шкала кадрів (унизу)</td><td data-th=\"Що в ній («Аніматор Ліцею»)\">номери кадрів, поточний кадр, кількість кадрів; ключові кадри позначено ◆</td></tr><tr><td data-th=\"Частина вікна\">Програвач</td><td data-th=\"Що в ній («Аніматор Ліцею»)\">кнопки «Відтворити / Пауза», «Зациклити», частота кадрів</td></tr></tbody></table></div><p>Вікно TupiTube складається з подібних частин: верхньої панелі, панелі інструментів, робочого поля, рядка стану тощо. Засоби створення анімації зібрано в модулі <b>Анімація</b>, а переглядають готову роботу в модулі <b>Програвач</b>.</p><h3><b>4. Створення проєкту</b></h3><p>Кожна анімація — це окремий проєкт. Під час створення проєкту задають його параметри:</p><ul><li>назву проєкту;</li><li>розмір кадру — ширину (X) і висоту (Y) у пікселях, наприклад 640×480;</li><li>частоту кадрів (кадрів/с), наприклад 24;</li><li>колір тла кадрів.</li></ul><p>Після підтвердження відкривається робоче поле. Прямокутник кольору тла в робочому полі — це перший кадр майбутнього «фільму». Тут малюють об'єкти, а також додають готові малюнки.</p><div class=\"def plus\"><span class=\"plusb\">⭐ для 12 балів</span> <b>Профіль проєкту</b> — готовий набір параметрів проєкту: розмір кадру й частота кадрів, наприклад «640×480 — 24». Якщо вибрати профіль зі списку, поля розміру й частоти кадрів заповнюються автоматично.</div><p>Як створити проєкт в «Аніматорі Ліцею»:</p><ol><li>натисни «Новий проєкт» на верхній панелі;</li><li>введи назву проєкту, задай розмір кадру, частоту кадрів і колір тла;</li><li>підтверди створення проєкту;</li><li>одразу натисни «Зберегти», щоб не загубити роботу.</li></ol><p class=\"nnote\"><i>У TupiTube, якщо не зберегти проєкт на початку роботи, час від часу з'являється вікно з нагадуванням; зміни після першого збереження зберігаються автоматично. В «Аніматорі Ліцею» проєкти зберігаються в браузері, тому відкривай свої проєкти («Мої проєкти») на тому самому пристрої й у тому самому браузері.</i></p><h3><b>5. Фігури та маркери</b></h3><p>Фігури малюють інструментами <b>Прямокутник</b>, <b>Еліпс</b>, <b>Трикутник</b>, <b>Лінія</b>: вибери інструмент на панелі інструментів і виконай перетягування в робочому полі. Інструмент <b>Текст</b> додає напис, <b>Малюнок</b> — готовий малюнок-емодзі, <b>Видалити</b> прибирає вибраний об'єкт. Щоб змінити вже намальовану фігуру, її вибирають інструментом <b>Вибір об'єкта</b>.</p><div class=\"def\"><b>Маркери</b> — точки навколо вибраного об'єкта; перетягуючи їх, об'єкт переміщують, змінюють його розміри або обертають.</div><p>Кожен маркер має своє призначення:</p><div class=\"ntable\"><table><thead><tr><th>Маркер</th><th>Що робить</th></tr></thead><tbody><tr><td data-th=\"Маркер\">Центральний</td><td data-th=\"Що робить\">переміщує об'єкт</td></tr><tr><td data-th=\"Маркер\">Кутові</td><td data-th=\"Що робить\">змінюють розміри об'єкта</td></tr><tr><td data-th=\"Маркер\">Верхній круглий («Аніматор Ліцею»)</td><td data-th=\"Що робить\">обертає об'єкт</td></tr></tbody></table></div><p class=\"nnote\"><i>У TupiTube кутові маркери зелені. Якщо двічі клацнути один із маркерів, вони стануть помаранчевими і слугуватимуть для обертання фігури.</i></p><h3><b>Завдання</b></h3><p class=\"ntask\"><b>Завдання 1.</b> Закінчи речення.</p><p>1) Анімацію отримують, якщо швидко показувати один за одним…</p><p>2) Частота кадрів — це…; її вимірюють у…</p><p>3) У мальованій анімації на кожному кадрі об'єкт подано…</p><p>4) Редактор двовимірної анімації — це програма, у якій…</p><p>5) Прямокутник кольору тла в робочому полі — це…</p><p class=\"ntask\"><b>Завдання 2.</b> Обчисли.</p><p>1) Анімація має 100 кадрів, частота кадрів — 25 кадр/с. Скільки секунд вона триває?</p><p>2) Скільки секунд триває анімація з 240 кадрів при частоті 24 кадр/с?</p><p>3) Скільки кадрів потрібно для анімації тривалістю 5 с при частоті 30 кадр/с?</p><p>4) Анімація з 48 кадрів триває 2 с. Яка в неї частота кадрів?</p><p class=\"ntask\"><b>Завдання 3.</b> Розподіли дії на дві групи: «задають під час створення проєкту» і «роблять потім, у робочому полі»: назва проєкту; малювання еліпса; частота кадрів; обертання фігури за маркер; колір тла; відтворення анімації; розмір кадру; напис інструментом «Текст».</p><p class=\"ntask\"><b>Завдання 4.</b> Знайди помилку. Максим записав у зошит такі речення. Знайди помилки й виправ їх.</p><p>1) Частоту кадрів вимірюють у пікселях.</p><p>2) Щоб перемістити фігуру, треба тягнути кутовий маркер.</p><p>3) Стандартна частота кадрів у кінотеатрах — 100 кадр/с.</p><p>4) Інструменти Прямокутник, Еліпс і Трикутник розташовані на шкалі кадрів.</p><p>5) Що більша частота кадрів, то довше триває анімація з тією самою кількістю кадрів.</p><p class=\"ntask\"><b>Завдання 5.</b> Так чи ні?</p><p>1) Якщо кадри змінюються достатньо часто, око не встигає сприйняти кожен малюнок окремо.</p><p>2) У телебаченні використовують частоту 24, 25 або 30 кадр/с.</p><p>3) TupiTube — платний редактор, який не працює на телефоні.</p><p>4) Колір тла кадрів задають під час створення проєкту.</p><p>5) Робоче поле розташоване на верхній панелі.</p><p>6) В «Аніматорі Ліцею» верхній круглий маркер обертає вибрану фігуру.</p><p class=\"ntask\"><b>Завдання 6.</b> Робота за комп'ютером (або телефоном) в «Аніматорі Ліцею». Створи проєкт «Стрибок».</p><p>1) Відкрий «Аніматор Ліцею» (musthav6.github.io/informatyka/animator.html).</p><p>2) На верхній панелі натисни «Новий проєкт». Назва — <b>Стрибок_Прізвище</b>, розмір кадру — 640×480, частота кадрів — 24 кадр/с, колір тла — світло-блакитний. Підтверди створення.</p><p>3) Одразу натисни «Зберегти».</p><p>4) Інструментами Прямокутник і Трикутник намалюй унизу робочого поля «гірку» — прямокутник і трикутник поруч.</p><p>5) Інструментом Еліпс намалюй м'яч ліворуч від трикутника.</p><p>6) Вибери м'яч інструментом «Вибір об'єкта». Потягни кутовий маркер — зміни розмір м'яча; потягни верхній круглий маркер — поверни його; потягни центральний маркер — пересунь м'яч.</p><p>7) Інструментом Текст додай напис «Стрибок», інструментом Малюнок — будь-який малюнок-емодзі.</p><p>8) На шкалі кадрів задай кількість кадрів — 24, перейди на кадр 24 і перетягни м'яч за центральний маркер праворуч від трикутника — на шкалі з'явиться позначка ◆. Натисни «Відтворити» на програвачі.</p><p>9) Натисни «Зберегти» й переконайся, що проєкт є в списку «Мої проєкти». Покажи роботу вчителеві.</p><p class=\"ntask\"><b>Завдання 7*.</b> Для тих, хто впорався швидше (⭐ — з повного конспекту).</p><p>1) Чим перекладна анімація відрізняється від мальованої? Яким способом створено «Казку про солом'яного бичка»?</p><p>2) Для проєкту вибрали профіль «640×480 — 24». Які параметри він задає? Скільки секунд триватиме анімація з 120 кадрів у цьому проєкті?</p><p>3) Виготов тауматроп: виріж картонний кружечок, з одного боку намалюй пташку, з другого — клітку, прив'яжи з боків дві нитки й швидко покрути. Поясни, чому малюнки зливаються в один.</p>",
"7-08": "<h3><b>1. Тло: статичне і динамічне</b></h3><p>У TupiTube об'єкт, намальований на кадрі, видно лише на цьому кадрі. Тому в першій анімації (§ 9) нерухомі трикутник і прямокутник з'являються лише на початку руху «м'яча», а потім зникають. Щоб нерухомі об'єкти було видно впродовж усієї анімації, їх переносять на особливий шар — <b>тло</b>. Тло розташоване позаду решти об'єктів анімації.</p><div class=\"def\"><b>Статичне тло</b> — зображення на тлі, яке впродовж перегляду анімації залишається нерухомим.</div><p>На статичному тлі розміщують зображення пейзажу чи інтер'єру, де відбувається дія анімаційного фільму, а також окремі об'єкти, які мають залишатися нерухомими: будинок, дерево, гори.</p><div class=\"def\"><b>Динамічне тло</b> — зображення на тлі, яке під час перегляду анімації прокручується в певному напрямку.</div><p>Для динамічного тла задають напрям руху (праворуч, ліворуч, угору, униз), величину зміщення тла на 1 кадр і щільність. Рухоме тло створює ілюзію руху інших об'єктів: якщо прокручується тло із зображенням дороги, здається, що рухається (насправді нерухомий) автомобіль.</p><div class=\"def plus\"><span class=\"plusb\">⭐ для 12 балів</span> <b>Зміщення динамічного тла</b> — відстань, на яку тло зсувається за один кадр. Що більше зміщення, то швидше рухається тло.</div><p>Приклад із підручника: зимова анімація. Сніговий покрив намальовано на статичному тлі, хмари — на динамічному (напрям — праворуч, зміщення — 5). У проєкті 100 кадрів при 24 кадр/с, тож анімація триває приблизно 4 с (100 : 24 ≈ 4).</p><h3><b>2. Векторне й растрове тло. Порядок шарів</b></h3><p>TupiTube має кілька режимів модуля Анімація, і їх можна використовувати одночасно:</p><div class=\"ntable\"><table><thead><tr><th>Режим</th><th>Що в ньому малюють</th></tr></thead><tbody><tr><td data-th=\"Режим\">Покадровий режим</td><td data-th=\"Що в ньому малюють\">об'єкти анімації, які змінюються від кадру до кадру</td></tr><tr><td data-th=\"Режим\">Режим статичного векторного тла</td><td data-th=\"Що в ньому малюють\">нерухоме тло з фігур</td></tr><tr><td data-th=\"Режим\">Режим динамічного векторного тла</td><td data-th=\"Що в ньому малюють\">рухоме тло з фігур</td></tr><tr><td data-th=\"Режим\">Режим статичного растрового тла</td><td data-th=\"Що в ньому малюють\">нерухоме тло, намальоване пензлями</td></tr><tr><td data-th=\"Режим\">Режим динамічного растрового тла</td><td data-th=\"Що в ньому малюють\">рухоме тло, намальоване пензлями</td></tr><tr><td data-th=\"Режим\">Режим векторного переднього плану</td><td data-th=\"Що в ньому малюють\">об'єкти попереду всіх інших (докладніше — на уроці 9)</td></tr></tbody></table></div><p>Отже, тло буває не лише статичним чи динамічним, а й векторним чи растровим.</p><div class=\"def plus\"><span class=\"plusb\">⭐ для 12 балів</span> <b>Векторне тло</b> — тло з векторних об'єктів — фігур, ліній, кривих, які малюють інструментами редактора анімації (вони подібні до інструментів векторного редактора Inkscape).</div><p>Векторне тло складається з окремих фігур, і кожну з них можна вибрати, пересунути чи перефарбувати.</p><div class=\"def plus\"><span class=\"plusb\">⭐ для 12 балів</span> <b>Растрове тло</b> — тло, яке малюють пензлями, як у растровому графічному редакторі. Пензель (наприклад, pointy-ink чи dry-brush) вибирають на панелі «Властивості пензля».</div><p>Щоб повернутися з растрового режиму TupiTube у головне вікно, вибирають команду Файл → Вийти з растрового режиму (Ctrl + Q).</p><div class=\"def plus\"><span class=\"plusb\">⭐ для 12 балів</span> <b>Порядок шарів тла</b> — розташування шарів тла відносно глядача: перший у списку шар розміщується найдалі від глядача, а кожен наступний — ближче.</div><p>У TupiTube вибраний шар переміщують у списку кнопками: угору — від глядача, униз — до глядача. Ще одна кнопка вмикає й вимикає видимість шару. Зміни підтверджують кнопкою «Застосувати».</p><p>В «Аніматорі Ліцею» на панелі «Шари» (під робочим полем) є чотири шари: «Статичне тло» (нерухомі об'єкти, їх видно на всіх кадрах), «Динамічне тло» (прокручується; для нього задають напрям і зміщення на 1 кадр), «Анімація» (об'єкти, що змінюються) і «Передній план» (нерухомі об'єкти попереду всіх інших). Перед тим як малювати, вибери потрібний шар.</p><p class=\"nnote\"><i>Перенести нерухомі об'єкти на тло в TupiTube можна так: вибрати їх, вирізати (Ctrl + X), перейти в режим статичного векторного тла і вставити (Ctrl + V).</i></p><h3><b>3. Колірна палітра: штрих і заповнення</b></h3><div class=\"def\"><b>Колірна палітра</b> — панель, на якій вибирають колір штриха (контуру) і колір заповнення (внутрішньої частини) об'єктів.</div><p>Кожна фігура має <b>штрих</b> — контур, обведення — і <b>заповнення</b> — колір усередині. Новостворені об'єкти одразу отримують кольори штриха й заповнення, вибрані на палітрі.</p><div class=\"ntable\"><table><thead><tr><th>Елемент палітри</th><th>Для чого</th></tr></thead><tbody><tr><td data-th=\"Елемент палітри\">Зразок кольору штриха</td><td data-th=\"Для чого\">показує й задає колір контуру</td></tr><tr><td data-th=\"Елемент палітри\">Зразок кольору заповнення</td><td data-th=\"Для чого\">показує й задає колір внутрішньої частини</td></tr><tr><td data-th=\"Елемент палітри\">Кнопка обміну кольорів</td><td data-th=\"Для чого\">міняє місцями кольори штриха й заповнення</td></tr><tr><td data-th=\"Елемент палітри\">Основні кольори</td><td data-th=\"Для чого\">швидкий вибір готового кольору</td></tr><tr><td data-th=\"Елемент палітри\">Код кольору (HEX)</td><td data-th=\"Для чого\">точний колір, наприклад #FF8800</td></tr><tr><td data-th=\"Елемент палітри\">Повзунки R, G, B</td><td data-th=\"Для чого\">кількість червоного, зеленого й синього (від 0 до 255)</td></tr><tr><td data-th=\"Елемент палітри\">Щільність</td><td data-th=\"Для чого\">рівень непрозорості (від 0 до 255)</td></tr></tbody></table></div><p>Змінити колір об'єкта, який уже намальовано, допомагає інструмент <b>Заповнення</b> (відерце): вибери потрібний колір на палітрі й клацни об'єкт. У TupiTube, якщо перед цим клацнути зразок кольору штриха, фарбуватимуться штрихи об'єктів, а якщо зразок кольору заповнення — заповнення.</p><h3><b>4. Коди кольорів і щільність</b></h3><p>Кожен колір на екрані складається з трьох світлових складових: червоної (R, red), зеленої (G, green) і синьої (B, blue). Змішуючи їх у різних кількостях, отримують будь-який колір.</p><div class=\"def\"><b>Код кольору</b> — запис кольору числами. У моделі RGB колір задають трьома числами від 0 до 255 — скільки в ньому червоного, зеленого й синього. Код HEX записує ці самі три числа після знака # шістнадцятковими цифрами — по дві на кожну складову.</div><p>0 означає, що складової немає зовсім, 255 — що її найбільше. У HEX-коді є цифри 0–9 і букви A–F: 00 — це 0, 80 — 128, FF — 255. Наприклад, #FFA500: FF — червоного 255, A5 — зеленого 165, 00 — синього 0; разом — помаранчевий.</p><div class=\"ntable wide\"><table><thead><tr><th>Колір</th><th>RGB (R, G, B)</th><th>HEX</th></tr></thead><tbody><tr><td data-th=\"Колір\">червоний</td><td data-th=\"RGB (R, G, B)\">255, 0, 0</td><td data-th=\"HEX\">#FF0000</td></tr><tr><td data-th=\"Колір\">зелений</td><td data-th=\"RGB (R, G, B)\">0, 255, 0</td><td data-th=\"HEX\">#00FF00</td></tr><tr><td data-th=\"Колір\">синій</td><td data-th=\"RGB (R, G, B)\">0, 0, 255</td><td data-th=\"HEX\">#0000FF</td></tr><tr><td data-th=\"Колір\">жовтий</td><td data-th=\"RGB (R, G, B)\">255, 255, 0</td><td data-th=\"HEX\">#FFFF00</td></tr><tr><td data-th=\"Колір\">бірюзовий (блакитний)</td><td data-th=\"RGB (R, G, B)\">0, 255, 255</td><td data-th=\"HEX\">#00FFFF</td></tr><tr><td data-th=\"Колір\">пурпуровий</td><td data-th=\"RGB (R, G, B)\">255, 0, 255</td><td data-th=\"HEX\">#FF00FF</td></tr><tr><td data-th=\"Колір\">помаранчевий</td><td data-th=\"RGB (R, G, B)\">255, 165, 0</td><td data-th=\"HEX\">#FFA500</td></tr><tr><td data-th=\"Колір\">сірий</td><td data-th=\"RGB (R, G, B)\">128, 128, 128</td><td data-th=\"HEX\">#808080</td></tr><tr><td data-th=\"Колір\">білий</td><td data-th=\"RGB (R, G, B)\">255, 255, 255</td><td data-th=\"HEX\">#FFFFFF</td></tr><tr><td data-th=\"Колір\">чорний</td><td data-th=\"RGB (R, G, B)\">0, 0, 0</td><td data-th=\"HEX\">#000000</td></tr></tbody></table></div><p>Щоб перекладати числа в HEX-код, зручно пам'ятати кілька пар:</p><div class=\"ntable\"><table><thead><tr><th>Число в RGB</th><th>У HEX-коді</th></tr></thead><tbody><tr><td data-th=\"Число в RGB\">0</td><td data-th=\"У HEX-коді\">00</td></tr><tr><td data-th=\"Число в RGB\">51</td><td data-th=\"У HEX-коді\">33</td></tr><tr><td data-th=\"Число в RGB\">102</td><td data-th=\"У HEX-коді\">66</td></tr><tr><td data-th=\"Число в RGB\">128</td><td data-th=\"У HEX-коді\">80</td></tr><tr><td data-th=\"Число в RGB\">153</td><td data-th=\"У HEX-коді\">99</td></tr><tr><td data-th=\"Число в RGB\">204</td><td data-th=\"У HEX-коді\">CC</td></tr><tr><td data-th=\"Число в RGB\">255</td><td data-th=\"У HEX-коді\">FF</td></tr></tbody></table></div><p>Якщо всі три складові однакові, колір сірий: що більші числа, то світліший. 0, 0, 0 — чорний, 255, 255, 255 — білий.</p><div class=\"def\"><b>Щільність</b> — рівень непрозорості кольору: 0 — повністю прозорий, 255 — повністю непрозорий.</div><p>Напівпрозорі хмари чи привид отримують, зменшивши щільність, наприклад до 120–130. Для динамічного тла в TupiTube щільність задають числом від 0 (повністю прозоре) до 1 (повністю непрозоре).</p><p class=\"nnote\"><i>У кодах на зразок #FF0000 стоять цифри нуль, а не літера О. HEX-код можна писати великими чи малими літерами: #ff8800 і #FF8800 — той самий колір.</i></p><h3><b>Завдання</b></h3><p class=\"ntask\"><b>Завдання 1.</b> Встав пропущені слова.</p><p>1) Статичне тло — зображення на тлі, яке впродовж перегляду анімації залишається…</p><p>2) Динамічне тло під час перегляду анімації… в певному напрямку.</p><p>3) Штрих — це… фігури, а заповнення — її…</p><p>4) Щільність 0 означає, що колір…, а 255 — що він…</p><p>5) У моделі RGB кожну складову кольору задають числом від… до…</p><p class=\"ntask\"><b>Завдання 2.</b> Розподіли на дві групи: «статичне тло» і «динамічне тло»: пейзаж села, де живуть герої; хмари, що пливуть небом; інтер'єр класу; дорога під автомобілем, який «їде»; гори на горизонті; сніг, що падає; річка, що пропливає повз човен; будинок, біля якого відбувається дія.</p><p class=\"ntask\"><b>Завдання 3.</b> Коди кольорів.</p><p>1) Назви колір: #FF0000; #000000; #FFFF00; RGB 0, 0, 255; RGB 255, 255, 255.</p><p>2) Запиши HEX-код кольорів: RGB 0, 255, 0; RGB 255, 0, 255.</p><p>3) Які значення R, G, B має колір #808080? Що це за колір?</p><p>4) Яким стане колір #FF0000, якщо значення G збільшити з 0 до 255? Запиши новий код і назви колір.</p><p class=\"ntask\"><b>Завдання 4.</b> Знайди помилку. Оля підготувала шпаргалку. Знайди помилки й виправ їх.</p><p>1) Штрих — це колір середини фігури.</p><p>2) Щільність 0 — повністю непрозорий колір.</p><p>3) Щоб дорога «їхала» під автомобілем, її малюють на статичному тлі.</p><p>4) #FFFFFF — чорний колір.</p><p>5) Колір уже намальованої фігури змінити не можна — її треба малювати заново.</p><p class=\"ntask\"><b>Завдання 5.</b> Що зробити, якщо…</p><p>1) будинок видно лише на першому кадрі, а він має бути на всіх кадрах;</p><p>2) хмари мають бути напівпрозорими;</p><p>3) колір штриха і колір заповнення переплутали, і їх треба поміняти місцями;</p><p>4) потрібен точно такий самий колір, як у логотипі класу, — #3366CC;</p><p>5) хмари на динамічному тлі мають пливти ліворуч, а не праворуч.</p><p class=\"ntask\"><b>Завдання 6.</b> Робота за комп'ютером (або телефоном) в «Аніматорі Ліцею». Створи проєкт «Зима».</p><p>1) Натисни «Новий проєкт». Назва — <b>Зима_Прізвище</b>, розмір кадру — 640×480, частота кадрів — 24 кадр/с, колір тла — світло-синій (код #99CCFF). Підтверди й натисни «Зберегти».</p><p>2) На панелі «Шари» вибери «Статичне тло». На колірній палітрі задай колір заповнення — білий (#FFFFFF), колір штриха — світло-сірий (#CCCCCC). Намалюй унизу кадру сніговий покрив (еліпсом або прямокутником).</p><p>3) На статичному тлі намалюй будиночок: стіни — прямокутник із заповненням #993300, дах — трикутник із заповненням #CC0000. Перевір кнопку обміну кольорів: що змінилося? Поверни кольори назад.</p><p>4) Намалюй сонце — жовте коло (R = 255, G = 204, B = 0). Перефарбуй один об'єкт інструментом «Заповнення».</p><p>5) Вибери шар «Динамічне тло». Задай на палітрі світло-сірий колір і щільність 180 та намалюй еліпсами 2–3 хмари. На панелі «Шари» для «Динамічного тла» задай напрям — праворуч, зміщення на 1 кадр — 5.</p><p>6) На шкалі кадрів задай кількість кадрів — 100. Натисни «Відтворити» й «Зациклити». Обчисли, скільки секунд триває анімація.</p><p>7) Зміни зміщення на 1, а потім на 10 і порівняй швидкість хмар. Залиш значення, яке подобається.</p><p>8) Натисни «Зберегти». Покажи роботу вчителеві.</p><p class=\"ntask\"><b>Завдання 7*.</b> Для тих, хто впорався швидше (⭐ — з повного конспекту).</p><p>1) Чим растрове тло відрізняється від векторного? Яке тло вибрати, щоб намалювати сонце пензлем? А щоб скласти будинок із прямокутника й трикутника?</p><p>2) Хмари на динамічному тлі зміщуються на 5 за кадр, а сніг — на 1. Що рухається швидше? Яке зміщення задати снігу, щоб він рухався втричі швидше?</p><p>3) У вікні шарів тла такий список: «Небо», «Гори», «Ліс». Який шар розміщено найдалі від глядача, а який — найближче? Як зробити, щоб «Гори» опинилися ближче до глядача, ніж «Ліс»?</p>",
"7-09": "<h3><b>1. Метод ключових кадрів</b></h3><p>Раніше художники-аніматори малювали кожен кадр вручну. Для 10-хвилинного фільму при частоті 25 кадр/с потрібно 10 · 60 · 25 = 15 000 малюнків! Комп'ютер значно пришвидшив роботу завдяки методу ключових кадрів, за якого більшість зображень об'єкта будується автоматично.</p><div class=\"def\"><b>Метод ключових кадрів</b> — спосіб автоматичного створення анімації, за якого розробник задає положення (форму, колір або інші властивості) об'єкта на деяких кадрах, а комп'ютер автоматично обчислює ці характеристики для проміжних кадрів.</div><p>Англійською метод називають keyframing: key — ключ, frame — кадр.</p><div class=\"def\"><b>Ключовий кадр</b> — кадр, на якому розробник сам задає положення, розмір, кут, колір чи інші властивості об'єкта.</div><p>В «Аніматорі Ліцею» ключові кадри позначено на шкалі кадрів знаком ◆.</p><div class=\"def\"><b>Проміжні кадри</b> — кадри між ключовими, які редактор обчислює (будує) автоматично.</div><p>Наприклад, на кадрі 1 м'яч ліворуч, а на кадрі 25 — праворуч. Це два ключові кадри. Редактор сам побудує 23 проміжні кадри, на яких м'яч поступово пересувається.</p><p>Як це зробити в «Аніматорі Ліцею»:</p><ol><li>намалюй об'єкт на шарі «Анімація» (кадр 1);</li><li>вибери його інструментом «Вибір об'єкта»;</li><li>на шкалі кадрів перейди на інший кадр, наприклад 25;</li><li>зміни положення, розмір, кут, колір або щільність об'єкта — на цьому кадрі з'явиться позначка ключового кадру ◆;</li><li>натисни «Відтворити» на програвачі: проміжні кадри редактор обчислить сам.</li></ol><h3><b>2. Інструмент «Вибір об'єкта». Параметри об'єкта</b></h3><p>Панель параметрів інструмента «Вибір об'єкта» в TupiTube містить такі операції:</p><div class=\"ntable\"><table><thead><tr><th>Операція</th><th>Що можна зробити</th></tr></thead><tbody><tr><td data-th=\"Операція\">Вирівнювання</td><td data-th=\"Що можна зробити\">вирівняти об'єкт у робочому полі: на горизонтальній осі, на вертикальній осі, у центрі</td></tr><tr><td data-th=\"Операція\">Відображення</td><td data-th=\"Що можна зробити\">віддзеркалити об'єкт горизонтально, вертикально або в обох напрямках</td></tr><tr><td data-th=\"Операція\">Порядок</td><td data-th=\"Що можна зробити\">перемістити об'єкт відносно глядача: позаду всіх, на рівень далі, попереду всіх, на рівень ближче</td></tr><tr><td data-th=\"Операція\">Групування</td><td data-th=\"Що можна зробити\">згрупувати або розгрупувати вибрані об'єкти</td></tr><tr><td data-th=\"Операція\">Розташування</td><td data-th=\"Що можна зробити\">задати координати X і Y об'єкта</td></tr><tr><td data-th=\"Операція\">Обертання</td><td data-th=\"Що можна зробити\">задати кут повороту за годинниковою стрілкою в градусах</td></tr><tr><td data-th=\"Операція\">Масштаб</td><td data-th=\"Що можна зробити\">змінити розміри: X — ширину, Y — висоту; прапорець «Пропорц.» змінює їх разом</td></tr></tbody></table></div><p>Початок координат — у лівому верхньому куті робочого поля, вісь X напрямлена праворуч, а вісь Y — донизу. Якщо малюнок складається з кількох частин (Колобок — тулуб, очі, рот), їх спершу групують, щоб ефект діяв на весь малюнок.</p><p>В «Аніматорі Ліцею» точні значення X, Y, ширини, висоти, кута й зсуву вибраного об'єкта вводять на панелі параметрів.</p><h3><b>3. Анімаційні ефекти</b></h3><p>За допомогою ключових кадрів можна автоматично змінювати не лише положення об'єкта, а й інші його властивості: кут повороту, розміри, прозорість, колір. У TupiTube для цього є інструменти групи Анімації:</p><div class=\"ntable wide\"><table><thead><tr><th>Ефект</th><th>Що змінюється</th><th>Основні параметри</th><th>Клавіші в TupiTube</th></tr></thead><tbody><tr><td data-th=\"Ефект\">Анімація переміщення</td><td data-th=\"Що змінюється\">положення: об'єкт рухається вздовж шляху</td><td data-th=\"Основні параметри\">шлях; початковий кадр; кількість кадрів на кожну ділянку шляху</td><td data-th=\"Клавіші в TupiTube\">Shift + W</td></tr><tr><td data-th=\"Ефект\">Анімація обертання</td><td data-th=\"Що змінюється\">кут повороту</td><td data-th=\"Основні параметри\">тип (неперервне чи часткове), напрям, швидкість (градусів за кадр)</td><td data-th=\"Клавіші в TupiTube\">Shift + R</td></tr><tr><td data-th=\"Ефект\">Анімація масштабування</td><td data-th=\"Що змінюється\">розміри</td><td data-th=\"Основні параметри\">як масштабувати (за шириною й висотою, лише за шириною, лише за висотою), коефіцієнт масштабування, число ітерацій</td><td data-th=\"Клавіші в TupiTube\">Shift + S</td></tr><tr><td data-th=\"Ефект\">Анімація зсуву</td><td data-th=\"Що змінюється\">нахил (перекіс) форми: прямокутник перекошується в паралелограм</td><td data-th=\"Основні параметри\">напрям зсуву, коефіцієнт, число ітерацій</td><td data-th=\"Клавіші в TupiTube\">Shift + H</td></tr><tr><td data-th=\"Ефект\">Анімація щільності</td><td data-th=\"Що змінюється\">прозорість: об'єкт поступово з'являється або зникає</td><td data-th=\"Основні параметри\">початкова й кінцева щільність, число ітерацій</td><td data-th=\"Клавіші в TupiTube\">Shift + O</td></tr><tr><td data-th=\"Ефект\">Анімація розмальовування (заповнення)</td><td data-th=\"Що змінюється\">колір штриха, заповнення або обох</td><td data-th=\"Основні параметри\">початковий і кінцевий кольори, число ітерацій</td><td data-th=\"Клавіші в TupiTube\">Shift + C</td></tr></tbody></table></div><p>Щоб у TupiTube додати до об'єкта ефект, вибирають інструмент ефекту й вводять назву ефекту, вибирають один або кілька об'єктів, задають властивості ефекту, зберігають його й переглядають результат у модулі Програвач. <b>Число ітерацій</b> — це кількість кадрів, протягом яких змінюється властивість.</p><div class=\"def\"><b>Траєкторія (шлях)</b> — лінія, уздовж якої рухається об'єкт в анімації переміщення.</div><p>Траєкторію будують подібно до кривої у векторному редакторі. Що більше кадрів відведено на ділянку шляху, то повільніше об'єкт її проходить; що менше — то швидше. Так Колобок швидко скочується з горба, а на горб викочується повільно.</p><p>В «Аніматорі Ліцею» шлях задають ключовими кадрами: на кожному ключовому кадрі ставлять об'єкт у нову точку. Що далі один від одного ключові кадри на шкалі, то повільніше рух між ними.</p><div class=\"ntable\"><table><thead><tr><th>Ефект</th><th>Як зробити в «Аніматорі Ліцею»</th></tr></thead><tbody><tr><td data-th=\"Ефект\">Переміщення</td><td data-th=\"Як зробити в «Аніматорі Ліцею»\">на іншому кадрі перетягнути об'єкт за центральний маркер</td></tr><tr><td data-th=\"Ефект\">Обертання</td><td data-th=\"Як зробити в «Аніматорі Ліцею»\">на іншому кадрі змінити кут (верхній круглий маркер або поле «кут»); для постійного обертання — ефект «Неперервне обертання» на панелі параметрів</td></tr><tr><td data-th=\"Ефект\">Масштабування</td><td data-th=\"Як зробити в «Аніматорі Ліцею»\">на іншому кадрі потягнути кутовий маркер або змінити ширину й висоту</td></tr><tr><td data-th=\"Ефект\">Щільність</td><td data-th=\"Як зробити в «Аніматорі Ліцею»\">на іншому кадрі змінити повзунок «Щільність» на колірній палітрі</td></tr><tr><td data-th=\"Ефект\">Зсув</td><td data-th=\"Як зробити в «Аніматорі Ліцею»\">на іншому кадрі змінити поле «Зсув, °» на панелі параметрів — фігура перекоситься</td></tr><tr><td data-th=\"Ефект\">Розмальовування</td><td data-th=\"Як зробити в «Аніматорі Ліцею»\">на іншому кадрі вибрати для об'єкта інший колір заповнення чи штриха</td></tr></tbody></table></div><h3><b>4. Обертання</b></h3><p>Для <b>неперервного обертання</b> задають напрям (за годинниковою стрілкою чи проти) і швидкість обертання в градусах на кадр. Повний оберт — 360°.</p><div class=\"ntable wide\"><table><thead><tr><th>Що треба знайти</th><th>Як обчислити</th><th>Приклад із підручника</th></tr></thead><tbody><tr><td data-th=\"Що треба знайти\">Скільки обертів зробить об'єкт</td><td data-th=\"Як обчислити\">градусів за кадр · кількість кадрів : 360°</td><td data-th=\"Приклад із підручника\">сонце: 3° за кадр, 120 кадрів → 120 · 3° = 360° — 1 оберт</td></tr><tr><td data-th=\"Що треба знайти\">На скільки градусів повертати за кадр</td><td data-th=\"Як обчислити\">кількість обертів · 360° : кількість кадрів</td><td data-th=\"Приклад із підручника\">Колобок: 3 оберти за 120 кадрів → 3 · 360° = 1080°, 1080° : 120 = 9° за кадр</td></tr></tbody></table></div><p>Крім неперервного, буває часткове обертання.</p><div class=\"def plus\"><span class=\"plusb\">⭐ для 12 балів</span> <b>Часткове обертання</b> — обертання лише в межах заданих кутів: крім напряму й швидкості, задають початковий і кінцевий кути повороту та спосіб повторення. Так анімують гойдалку: від 340° до 20°, 1 градус за кадр, «зациклити з реверсом».</div><p>Для гойдалки центр обертання переносять у точку опори — тоді дошка з дітьми нахиляється то в один, то в інший бік.</p><div class=\"def plus\"><span class=\"plusb\">⭐ для 12 балів</span> <b>Зациклити з реверсом</b> — спосіб повторення ефекту, за якого він відтворюється то в прямому, то у зворотному напрямку. Просто «зациклити» — повторення щоразу з початку.</div><p>В «Аніматорі Ліцею» неперервне обертання вмикають на панелі параметрів: ефект «Неперервне обертання» (градусів/кадр). Часткове обертання можна зробити ключовими кадрами: на одному кадрі задати один кут, на іншому — інший.</p><h3><b>5. Кілька ефектів для одного об'єкта. Передній план</b></h3><p>До одного об'єкта можна додати кілька анімаційних ефектів. Колобок, який лише рухається траєкторією, ковзає; якщо додати ще й обертання (9° за кадр), він справді котиться. Полум'я вогнища може водночас змінювати колір (розмальовування), розмір (масштабування) і щільність.</p><div class=\"def plus\"><span class=\"plusb\">⭐ для 12 балів</span> <b>Коефіцієнт масштабування</b> — множник, на який змінюються розміри об'єкта на наступному кадрі порівняно з поточним. Наприклад, за коефіцієнта 1,05 на кожному кадрі об'єкт більшає на 5 %.</div><p>Приклад: мерехтлива зірка — масштабування за шириною й висотою, коефіцієнт 1,050, число ітерацій 20, «зациклити з реверсом»: зірка то більшає, то меншає.</p><div class=\"def plus\"><span class=\"plusb\">⭐ для 12 балів</span> <b>Передній план</b> — шар, розташований попереду всіх об'єктів анімації (у TupiTube — режим векторного переднього плану). На ньому розміщують те, що має закривати інші об'єкти.</div><p>Наприклад, у вогнищі нижній край полум'я прямий і має неприродний вигляд. Якщо перенести зображення дров на передній план, дрова закриють край полум'я. У режимі переднього плану, як і в режимах тла, інших шарів не видно.</p><h3><b>Завдання</b></h3><p class=\"ntask\"><b>Завдання 1.</b> Поясни своїми словами.</p><p>1) Що таке метод ключових кадрів?</p><p>2) Чим ключовий кадр відрізняється від проміжного?</p><p>3) Що таке траєкторія (шлях)?</p><p>4) Ключові кадри — 1 і 25. Скільки проміжних кадрів обчислить редактор?</p><p class=\"ntask\"><b>Завдання 2.</b> Що змінює кожен ефект? Для кожного ефекту (переміщення, обертання, масштабування, зсув, щільність, розмальовування) знайди властивість: колір; прозорість; кут повороту; положення; розміри; нахил форми. Потім добери ефект до прикладу: сонце крутиться; привид поступово зникає; зірка пульсує; Колобок котиться з горба; полум'я з червоного стає жовтим.</p><p class=\"ntask\"><b>Завдання 3.</b> Обчисли.</p><p>1) Скільки малюнків потрібно для 10-хвилинного фільму при 25 кадр/с, якщо кожен кадр малювати вручну?</p><p>2) Сонце повертається на 3° за кадр. Скільки повних обертів воно зробить за 120 кадрів?</p><p>3) За 120 кадрів Колобок має зробити 3 повні оберти. На скільки градусів треба повертати його на кожному кадрі?</p><p>4) На який кут має повертатися об'єкт на кожному кадрі, щоб в анімації з 720 кадрів він здійснив 5 обертів?</p><p class=\"ntask\"><b>Завдання 4.</b> Знайди помилку. Петро пояснює молодшому братові, як створюють анімацію. Знайди помилки й виправ їх.</p><p>1) За методом ключових кадрів людина малює кожен кадр, а комп'ютер лише показує їх.</p><p>2) Щоб Колобок проходив ділянку шляху повільніше, на неї треба відвести менше кадрів.</p><p>3) Анімація щільності змінює розміри об'єкта.</p><p>4) Швидкість неперервного обертання задають у кадрах на секунду.</p><p>5) До одного об'єкта можна додати лише один ефект.</p><p class=\"ntask\"><b>Завдання 5.</b> Так чи ні?</p><p>1) Проміжні кадри редактор обчислює автоматично.</p><p>2) Повний оберт — це 360°.</p><p>3) Анімація розмальовування змінює колір штриха, заповнення або обох разом.</p><p>4) Щоб об'єкт поступово з'явився, щільність має змінюватися від найбільшої до 0.</p><p>5) Перед додаванням ефекту частини малюнка Колобка варто згрупувати.</p><p>6) Анімація масштабування змінює кут повороту об'єкта.</p><p class=\"ntask\"><b>Завдання 6.</b> Робота за комп'ютером (або телефоном) в «Аніматорі Ліцею». Створи проєкт «Казка».</p><p>1) Натисни «Новий проєкт». Назва — <b>Казка_Прізвище</b>, розмір кадру — 640×480, частота кадрів — 25 кадр/с, колір тла — світлий. Підтверди й натисни «Зберегти». На шкалі кадрів задай кількість кадрів — 120.</p><p>2) На шарі «Статичне тло» намалюй краєвид: зелений пагорб (трикутник або еліпс) посередині кадру й землю внизу.</p><p>3) Вибери шар «Анімація». Інструментом Малюнок додай сонце (малюнок-емодзі) у верхньому куті. На панелі параметрів увімкни для нього «Неперервне обертання» — 3 градуси/кадр.</p><p>4) Інструментом Малюнок додай Колобка (круглий малюнок-емодзі) біля лівого краю кадру — це кадр 1.</p><p>5) На шкалі кадрів перейди на кадр 60 і постав Колобка на вершину пагорба; потім на кадр 80 — до підніжжя праворуч; на кадр 120 — до правого краю. Біля кожного з цих кадрів з'явиться ◆.</p><p>6) Увімкни для Колобка «Неперервне обертання» — 9 градусів/кадр.</p><p>7) Натисни «Відтворити»: Колобок повільно викочується на горб, швидко скочується й котиться далі, сонце обертається. Обчисли, скільки обертів робить Колобок за 120 кадрів.</p><p>8) Додай зірку, яка поступово з'являється: на кадрі 1 задай їй щільність 0, на кадрі 60 — 255.</p><p>9) Натисни «Зберегти». Покажи роботу вчителеві.</p><p class=\"ntask\"><b>Завдання 7*.</b> Для тих, хто впорався швидше (⭐ — з повного конспекту).</p><p>1) Чим часткове обертання відрізняється від неперервного? Які параметри задати для гойдалки?</p><p>2) Що означає «зациклити з реверсом»? Наведи приклад, коли це доречно.</p><p>3) Ширина зірки — 100 пікселів, коефіцієнт масштабування — 1,05. Якою буде ширина на наступному кадрі? А ще через один кадр?</p><p>4) Навіщо в анімації вогнища дрова переносять на передній план?</p>"
});
